import io, json, zipfile, pickle, struct, sys

MODEL='/app/model.pth'
OUT='/app/weights.json'

DTYPES={
 'float32':('f',4),'float':('f',4),'FloatStorage':('f',4),
 'float64':('d',8),'double':('d',8),'DoubleStorage':('d',8),
 'float16':('e',2),'half':('e',2),'HalfStorage':('e',2),
 'int64':('q',8),'long':('q',8),'LongStorage':('q',8),
 'int32':('i',4),'int':('i',4),'IntStorage':('i',4),
 'int16':('h',2),'short':('h',2),'ShortStorage':('h',2),
 'int8':('b',1),'char':('b',1),'CharStorage':('b',1),
 'uint8':('B',1),'byte':('B',1),'ByteStorage':('B',1),
 'bool':('?',1),'BoolStorage':('?',1),
}

class DType:
    def __init__(self,code,size):
        self.code=code; self.size=size
class Storage:
    def __init__(self,dtype,data):
        self.dtype=dtype; self.data=data

def rebuild(*args):
    storage=args[0]; offset=args[1]; size=args[2]; stride=args[3]
    dt=storage.dtype; itemsize=dt.size
    total=1
    for s in size: total*=s
    start=offset*itemsize
    raw=storage.data[start:start+total*itemsize]
    vals=list(struct.unpack('<%d%s'%(total,dt.code),raw))
    def rsf(a,d):
        if len(d)==1: return a
        n=d[0]; sub=len(a)//n
        return [rsf(a[i*sub:(i+1)*sub],d[1:]) for i in range(n)]
    return rsf(vals,list(size))

class UP(pickle.Unpickler):
    def __init__(self,file,zf):
        super().__init__(file); self.zf=zf
    def find_class(self,module,name):
        if name in DTYPES:
            c,s=DTYPES[name]; return DType(c,s)
        if module=='torch._utils' and name in ('_rebuild_tensor_v2','_rebuild_tensor'):
            return rebuild
        if module=='torch.storage' and name=='_load_from_bytes':
            return lambda b: b
        if module=='collections' and name=='OrderedDict':
            return dict
        return super().find_class(module,name)
    def persistent_load(self,pid):
        if isinstance(pid,tuple) and pid[0]=='storage':
            dt=pid[1]
            if not isinstance(dt,DType):
                key=str(dt)
                if key.startswith('<class'):
                    key=key.split('.')[-1].split("'")[0]
                c,s=DTYPES.get(key,(None,None))
                if c is None:
                    raise pickle.UnpicklingError('unknown dtype %r'%dt)
                dt=DType(c,s)
            key=str(pid[2])
            data=self.zf.read('archive/data/'+key)
            return Storage(dt,data)
        raise pickle.UnpicklingError('bad pid %r'%pid)

def main():
    zf=zipfile.ZipFile(MODEL)
    names=zf.namelist()
    pk=[n for n in names if n.endswith('data.pkl')]
    if not pk:
        print('NOT A ZIP STATE_DICT',file=sys.stderr); sys.exit(1)
    pkl=zf.read(pk[0])
    obj=UP(io.BytesIO(pkl),zf).load()
    if isinstance(obj,dict) and 'state_dict' in obj:
        obj=obj['state_dict']
    print('keys:',list(obj.keys()),file=sys.stderr)
    groups={}
    for k,v in obj.items():
        if k.endswith('.weight'):
            pre=k[:-len('.weight')]; groups.setdefault(pre,{})['weight']=v
        elif k.endswith('.bias'):
            pre=k[:-len('.bias')]; groups.setdefault(pre,{})['bias']=v
        else:
            print('UNKNOWN KEY',k,file=sys.stderr)
    layers=[]
    for pre,g in groups.items():
        w=g['weight']; b=g['bias']
        rows=len(w); cols=len(w[0])
        flat=[]
        for r in w: flat.extend(r)
        layers.append({'pre':pre,'rows':rows,'cols':cols,'weight':flat,'bias':list(b)})
    ordered=[]; rem=layers[:]
    first=[l for l in rem if l['cols']==784]
    if first:
        cur=first[0]; ordered.append(cur); rem.remove(cur)
        while rem:
            nxt=[l for l in rem if l['cols']==cur['rows']]
            if not nxt:
                ordered.extend(rem); break
            cur=nxt[0]; ordered.append(cur); rem.remove(cur)
    else:
        ordered=layers
    print('order:',[l['pre'] for l in ordered],file=sys.stderr)
    out={'layers':[{'rows':l['rows'],'cols':l['cols'],'weight':l['weight'],'bias':l['bias']} for l in ordered]}
    with open(OUT,'w') as f:
        json.dump(out,f)
    print('wrote',OUT,file=sys.stderr)

