        super().__init__(file); self.zf=zf
    def find_class(self,module,name):
        if name in DTYPES:
            c,s=DTYPES[name]; return DType(c,s)
        if module=='torch._utils' and name in ('_rebuild_tensor_v2','_rebuild_tensor'):
            return rebuild
        if module=='torch.storage' and name=='_load_from_bytes':
            return lambda b: b
        if module=='collections' and name=='OrderedDict':
            return dict
        return super().find_class(module,name)
    def persistent_load(self,pid):
        if isinstance(pid,tuple) and pid[0]=='storage':
            dt=pid[1]
            if not isinstance(dt,DType):
                key=str(dt)
                if key.startswith('<class'):
                    key=key.split('.')[-1].split("'")[0]
                c,s=DTYPES.get(key,(None,None))
                if c is None:
                    raise pickle.UnpicklingError('unknown dtype %r'%dt)
                dt=DType(c,s)
            key=str(pid[2])
            data=self.zf.read('archive/data/'+key)
            return Storage(dt,data)
        raise pickle.UnpicklingError('bad pid %r'%pid)

