#include <math.h>
#include "cJSON.h"
#include "lodepng.h"

typedef struct {
    int rows, cols;
    double* W;
    double* b;
} Layer;

static char* read_file(const char* path){
    FILE* f=fopen(path,"rb");
    if(!f){ fprintf(stderr,"cannot open %s\n",path); exit(1);}
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char* buf=malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f);
    return buf;
}

int main(int argc,char** argv){
    if(argc<3){ fprintf(stderr,"usage: %s weights.json image.png\n",argv[0]); return 1; }
    char* json=read_file(argv[1]);
    cJSON* root=cJSON_Parse(json);
    if(!root){ fprintf(stderr,"json parse error\n"); return 1; }
    cJSON* larr=cJSON_GetObjectItem(root,"layers");
    int nl=cJSON_GetArraySize(larr);
    Layer* L=malloc(sizeof(Layer)*nl);
    for(int li=0; li<nl; li++){
        cJSON* lj=cJSON_GetArrayItem(larr,li);
        cJSON* r=cJSON_GetObjectItem(lj,"rows");
        cJSON* c=cJSON_GetObjectItem(lj,"cols");
        cJSON* w=cJSON_GetObjectItem(lj,"weight");
        cJSON* b=cJSON_GetObjectItem(lj,"bias");
        L[li].rows=(int)r->valuedouble;
        L[li].cols=(int)c->valuedouble;
        int rows=L[li].rows, cols=L[li].cols;
        L[li].W=malloc(sizeof(double)*rows*cols);
        L[li].b=malloc(sizeof(double)*rows);
        int n=cJSON_GetArraySize(w);
        for(int i=0;i<n;i++) L[li].W[i]=cJSON_GetArrayItem(w,i)->valuedouble;
        n=cJSON_GetArraySize(b);
        for(int i=0;i<n;i++) L[li].b[i]=cJSON_GetArrayItem(b,i)->valuedouble;
    }
    free(json);
    unsigned char* img=NULL; unsigned w=0,h=0;
    unsigned err=lodepng_decode32_file(&img,&w,&h,argv[2]);
    if(err){ fprintf(stderr,"png error %s\n",lodepng_error_text(err)); return 1; }
    int N=(int)(w*h);
    double* x=malloc(sizeof(double)*N);
    double mean=0;
    for(int i=0;i<N;i++){ double v=img[i*4]/255.0; x[i]=v; mean+=v; }
    mean/=N;
    if(mean>0.5){ for(int i=0;i<N;i++) x[i]=1.0-x[i]; }
#ifdef NORMALIZE
    for(int i=0;i<N;i++) x[i]=(x[i]-0.1307)/0.3081;
#endif
    free(img);
    double* z=x; int zs=N;
    for(int li=0; li<nl; li++){
        int rows=L[li].rows, cols=L[li].cols;
        double* nz=malloc(sizeof(double)*rows);
        for(int j=0;j<rows;j++){
            double s=L[li].b[j];
            for(int k=0;k<cols;k++) s+=L[li].W[j*cols+k]*z[k];
            if(li!=nl-1 && s<0) s=0;
            nz[j]=s;
        }
        if(z!=x) free(z);
        z=nz; zs=rows;
    }
    int best=0; double bv=z[0];
    for(int i=1;i<zs;i++){ if(z[i]>bv){ bv=z[i]; best=i; } }
    printf("%d\n",best);
    return 0;
}
